source='''from collections import Counter, defaultdict

def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(out), len(out[0])
    # Infer the repeated diagonal color cycle from the visible interior.
    best = None
    for period in range(2, 11):
        counts = defaultdict(Counter)
        for r in range(3, h):
            for c in range(3, w):
                value = out[r][c]
                if value != 0:
                    counts[(r + c) % period][value] += 1
        score = sum(max(bucket.values()) for bucket in counts.values())
        mapping = {residue: bucket.most_common(1)[0][0]
                   for residue, bucket in counts.items()}
        candidate = (score, -period, mapping)
        if best is None or candidate[:2] > best[:2]:
            best = candidate
    mapping = best[2]
    fallback = next(iter(mapping.values()))
    for r in range(h):
        for c in range(w):
            if out[r][c] != 0:
                continue
            if (r == 2 and c >= 2) or (c == 2 and r >= 2):
                out[r][c] = 4
            elif r < 2 or c < 2:
                out[r][c] = 1
            else:
                out[r][c] = mapping.get((r + c) % (-best[1]), fallback)
    return out
